import VideoSlideshow from './sections/video-swiper.js';
import { downloadFileByLink, isMobile  } from '@utils/index.js'
import { getManualList } from '@utils//fetch.js';
import './user-guide.css'

class UserGuide {
    constructor(el) {
      this.DOM = { el };
      this.config = { pdf: {}, maintenance: null, video: null };
      this.downloadText = $('.manuals').data('download-text')
      this.more = $('.manuals').data('more')
      this.less = $('.manuals').data('less')

      this.pdf();
      this.maintenance();
      this.faq();
      this.video()
    }

    $$(entity) {
      return entity ? document.querySelector(entity) : null
    }

    all(entity) {
      // return entity ? document.querySelectorAll(entity) : []
      return entity ? $(entity).get() : []
    }

    tab(li, content, search) {
      li.forEach((item, index, arr) => {
        item.onclick = () => {
          arr.forEach((v) => { v.classList.remove("active") });
          content.forEach((v) => { v.classList.remove("active") });
          item.classList.add("active");
          content[index].classList.add("active");
          search && search()
        }
      })
    }

    pdf() {
      const me = this;
      function renderHtml(data) {
        const val = $(".pdf .search-box input").val().trim();
        const list = val ? data.filter(item => item.originTitle.includes(val.trim())) : data
        if (list.length > 0) {
          let html = ''
          list.forEach(item => {
            html += `
              <li>
                <i class="img-icon iconfont jackery-icon-pdf"></i>
                <b class="text-sm">${item.originTitle}</b>
                <button class="z-button-fill-middle" data-link="${item.introduceBookUrlDesc}">
                  <i class="iconfont jackery-icon-download text-sm"></i>
                  ${me.downloadText}
                </button>
              </li>
            `
          })
          $('.manuals-list').html(
            `<ul class="list tab-content active">${html}</ul>`
          )
          if(isMobile()){
            list.length > 4 ? $(".more").show() : $('.more').hide()
          }else{
            list.length > 8 ? $(".more").show() : $('.more').hide()
          }
        } else {
          const html = `
            <div class="search-result">
              <h2 class="section-container text-2xl text-center">${window.userGuideString.noresults}</h2>
              <div class="resaults_empty text-center">
                <img class="object-cover" src="https://cdn.shopify.com/s/files/1/0550/0524/9633/files/IP.png?v=1675326479" alt="${window.userGuideString.noresults}">
              </div>
            </div>
          `
          $('.manuals-list').html(html)
        }
      }

      async function getList(collectionHandle) {
        const params = {
          collectionHandle
        }
        const { data } = await getManualList(params)
        me.config.pdf.list = data
        renderHtml(data)
      }

      const getFirstLi = () => {
        const first = $('.manuals-tab li').eq(0)
        first.addClass('active')
        const handle = first.data('handle')
        if (handle){
          getList(handle)
        }else{
          const type = first.data('type');
          const tabName = first.text().trim();

          if (type === 'new') {
            const data = document.querySelector("#user-guide-json") ? JSON.parse(document.querySelector("#user-guide-json").innerText) : [];
            const firstNewTabName = $('.manuals-tab li[data-type="new"]').first().text().trim();
            const filteredData = data.filter(item => {
              return item.originName ? item.originName === tabName : tabName === firstNewTabName;
            });

            me.config.pdf.list = filteredData;
            renderHtml(filteredData);
          }
        }
      }

      getFirstLi()

      // tab点击
      $('.manuals-tab li').click(function() {
        const type = $(this).data('type');
        const tabName = $(this).text().trim();

        if (type === 'new') {
          const data = document.querySelector("#user-guide-json") ? JSON.parse(document.querySelector("#user-guide-json").innerText) : [];
          const firstNewTabName = $('.manuals-tab li[data-type="new"]').first().text().trim();
          const filteredData = data.filter(item => {
            return item.originName ? item.originName === tabName : tabName === firstNewTabName;
          });

          me.config.pdf.list = filteredData;
          renderHtml(filteredData);
        } else {
          const handle = $(this).data('handle');
          getList(handle);
        }

        // 设置选中状态
        $(this).addClass('active').siblings().removeClass('active');
      });
      // 下载文件
      $('.pdf .manuals-list').on('click', 'button', async function() {
        $(this).attr('disabled', true)
        const richText = $(this).html();
        $(this).html('Loading')
        await downloadFileByLink($(this).data('link'))
        $(this).html(richText)
        $(this).attr('disabled', false)
      })

      $('.pdf .search-box button').click(function() {
        renderHtml(me.config.pdf.list)
      })

      let position = 0;
      if(!$(".manuals.pdf .more")) return
      $(".manuals.pdf .more").click(function() {
        if($(".manuals.pdf").hasClass('minimum')) {
          position = document.documentElement.scrollTop || document.body.scrollTop || window.pageYOffset;
          $(".manuals.pdf").removeClass('minimum')
          $(".manuals.pdf .more span").text(me.less)
        } else {
          $(".manuals.pdf").addClass('minimum')
          $(".manuals.pdf .more span").text(me.more)
        }

      })
    }

    maintenance() {
      const me = this;

      function modal(data, _class, db) {
        const m = document.createElement('aside');
        m.className = `yModal ${_class || ""}`;
        m.innerHTML = `
          <i class="mask"></i>
          <div class="y-modal-body">
            <svg class="icon icon-close" viewBox="0 0 64 64"><path d="M19 17.61l27.12 27.13m0-27.12L19 44.74"></path></svg>
            <img src="${data.image}" alt="${data.title}">
            <div class="content">
              <h4>${data.title}</h4>
              ${data.content}
            </div>
          </div>
        `;
        document.body.appendChild(m);

        me.$$(".yModal .icon-close").onclick = me.$$(".yModal .mask").onclick = () => {
          document.body.removeChild(m);
          db && db()
        }
      }
      function learn(el, type) {
        el.forEach((item, index) => {
          item.querySelector("button").onclick = () => { modal(me.config.maintenance[type][index]) }
        })
      }

      me.config.maintenance = JSON.parse(me.$$("#product-maintenance").innerText);

      me.tab(me.all('.maintenance .tab li'), me.all('.maintenance .tab-content'));

      learn(me.all(".maintenance .tab-content.pps li"), "pps");
      learn(me.all(".maintenance .tab-content.sp li"), "sp")
    }

    faq() {
      const me = this;
      me.tab(me.all('.faq .tab li'), me.all('.faq .tab-content'));
      if (me.all('.faq .tab li.active')) {
        me.all('.faq .tab li')[0].classList.add("active");
        me.all('.faq .tab-content')[0].classList.add("active");
      }
      // view more
      $(".faq .z-button-fill-middle").click(function() {
        $(this).parent().hasClass("minimum") ? $(this).parent().removeClass("minimum") : $(this).parent().addClass("minimum")
      })
    }

    video() {
      const me = this;
      let DOM = document.querySelector('.manuals.video');

      const video = new VideoSlideshow(document.querySelector('.video-slideshow'));
      function getYoutubeID(src) {
        if(src.indexOf("youtube.com/watch") !== -1) {
          return src.split("v=")[1].split("&")[0]
        }

        if(src.indexOf("youtube.com/embed") !== -1) {
          return src.split("embed/")[1].split("?")[0]
        }
      }
      function search() {
        const input = DOM.querySelector(".search-box input");
        const videoSlide = DOM.querySelector(".video-slideshow");
        const { type } = DOM.querySelector(".tab li.active").dataset;
        const data = input.value ? me.config.video[type].filter((v) => new RegExp(input.value).test(v.title)) : me.config.video[type];

        // 先销毁原先的video swiper
        video.destroy(() => {
          let html = "";
          data.forEach((item, index) => {
            const video_dom = (item.video_url.indexOf('youtube.com/watch') !== -1 || item.video_url.indexOf('youtube.com/embed') !== -1) ? `<div 
            id="Videoslide__type_${index}" 
            class="product__video" 
            data-video-type="youtube" 
            data-video-style="muted"
            data-youtube-id="${getYoutubeID(item.video_url)}"
        >
        </div>`:`<video 
        id="Videoslide__type_${index}" 
        class="product__video" 
        data-video-type="mp4" 
        data-video-style="muted" 
        loop
        muted
        webkit-playsinline="true"
        playsinline="true"
    >
        <source
            src="${item.video_url}"
            type="video/mp4"
        >
    </video>`

            html += `
            <div class="swiper-slide slide swiper_slide_video">
              ${video_dom}
              <div class="slide-content absolute">
                <span class="slide-title h3">${item.title}</span>
                <a class="slide-link h5 underlines-btn" href="${item.link}">${item.link_text}<span class="iconfont jackery-icon-arrow-right"></span></a>
              </div>
              <div class="absolute mobile-block video-swiper-play" data-modal="#s${item.id}">
                <span class="iconfont jackery-icon-playCircle"></span>
              </div>
            </div>
            `;
          })
          me.$$(".manuals.video .video-slideshow .swiper-wrapper").innerHTML = html
        });

        videoSlide.style.display = "none";
        if (data.length > 0) {
          DOM.querySelector(".search-result") && DOM.querySelector(".search-result").remove();
          videoSlide.style.display = "";
          video.init()
        } else {
          if (DOM.querySelector(".search-result")) { return }
          let no_result = document.createElement("div");
          no_result.className = "search-result";
          no_result.innerHTML = `
            <h2 class="section-container text-2xl text-center">${window.userGuideString.noresults}</h2>
            <div class="resaults_empty text-center">
              <img class="object-cover" src="https://cdn.shopify.com/s/files/1/0550/0524/9633/files/IP.png?v=1675326479" alt="${window.userGuideString.noresults}">
            </div>
          `;
          DOM.insertBefore(no_result, videoSlide)
        }
      }

      me.config.video = JSON.parse(document.querySelector("#user-guide-video").innerText);
      DOM = document.querySelector(".manuals.video");

      me.all('.manuals.video .tab li').forEach((item, index, arr) => {
        item.onclick = () => {
          arr.forEach((v) => { v.classList.remove("active") });
          item.classList.add("active");
          search()
        }
      });
      DOM.querySelector(".search-box button").onclick = () => search()
    }
  }

  $(document).ready(function() {
    new UserGuide();
  })
